def finalString(s: str) -> str:
    """
    Simulates typing on a faulty keyboard where the character 'i' 
    reverses the current string on the screen.
    """
    res = []
    for char in s:
        if char == 'i':
            res.reverse()
        else:
            res.append(char)
    return "".join(res)
