def isValid(word: str) -> bool:
    # Check minimum length requirement
    if len(word) < 3:
        return False

    vowels = set("aeiouAEIOU")
    has_vowel = False
    has_consonant = False

    for char in word:
        # Check if character is alphanumeric
        if not char.isalnum():
            return False

        # Check if character is a letter
        if char.isalpha():
            if char in vowels:
                has_vowel = True
            else:
                has_consonant = True

    # Word is valid if it contains at least one vowel and one consonant
    return has_vowel and has_consonant
