def findLatestTime(s: str) -> str:
    s_list = list(s)

    # Handle Hours (HH)
    # HH must be between 00 and 11
    if s_list[0] == '?':
        # If s[1] is '?', we can pick '1' for the first digit to make it '11'
        # If s[1] is '0' or '1', we can pick '1'
        # If s[1] is > '1', we must pick '0' (e.g., 02, 03...)
        if s_list[1] == '?' or int(s_list[1]) <= 1:
            s_list[0] = '1'
        else:
            s_list[0] = '0'

    if s_list[1] == '?':
        # If s[0] is '1', the max for s[1] is '1' (to get 11)
        # If s[0] is '0', the max for s[1] is '9' (to get 09)
        if s_list[0] == '1':
            s_list[1] = '1'
        else:
            s_list[1] = '9'

    # Handle Minutes (MM)
    # MM must be between 00 and 59
    if s_list[3] == '?':
        # Max tens place for minutes is 5
        s_list[3] = '5'

    if s_list[4] == '?':
        # Max units place for minutes is 9
        s_list[4] = '9'

    return "".join(s_list)
