import sys

def solve():
    # Read input and group into three 4x4 polyominoes
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    raw_polys = []
    for i in range(3):
        grid = []
        for j in range(4):
            grid.append(input_data[i * 4 + j])
        raw_polys.append(grid)

    # Convert grid to a list of (r, c) coordinates relative to the first '#'
    def get_coords(grid):
        coords = []
        for r in range(4):
            for c in range(4):
                if grid[r][c] == '#':
                    coords.append((r, c))
        return coords

    # Rotate coordinates 90 degrees clockwise
    def rotate(coords):
        # (r, c) -> (c, -r)
        return [(c, -r) for r, c in coords]

    # Normalize coordinates so the top-left-most square is (0, 0)
    def normalize(coords):
        min_r = min(r for r, c in coords)
        min_c = min(c for r, c in coords)
        return sorted([(r - min_r, c - min_c) for r, c in coords])

    # Generate all 4 rotations for a polyomino
    def get_rotations(coords):
        rots = []
        curr = coords
        for _ in range(4):
            rots.append(normalize(curr))
            curr = rotate(curr)
        # Remove duplicates (e.g., for symmetric shapes)
        unique_rots = []
        for r in rots:
            if r not in unique_rots:
                unique_rots.append(r)
        return unique_rots

    poly_coords = [get_coords(p) for p in raw_polys]

    # Total '#' must be exactly 16 to fill a 4x4 grid
    if sum(len(c) for c in poly_coords) != 16:
        print("No")
        return

    poly_rotations = [get_rotations(c) for c in poly_coords]

    # Try all combinations of rotations and translations
    # poly_rotations[0] is fixed to reduce search space, but we must translate it
    for p0 in poly_rotations[0]:
        for dr0 in range(-3, 4):
            for dc0 in range(-3, 4):
                s0 = set((r + dr0, c + dc0) for r, c in p0)
                # Check if p0 is within bounds
                if any(not (0 <= r < 4 and 0 <= c < 4) for r, c in s0):
                    continue

                for p1 in poly_rotations[1]:
                    for dr1 in range(-3, 4):
                        for dc1 in range(-3, 4):
                            s1 = set((r + dr1, c + dc1) for r, c in p1)
                            if any(not (0 <= r < 4 and 0 <= c < 4) for r, c in s1):
                                continue
                            if not s0.isdisjoint(s1):
                                continue

                            for p2 in poly_rotations[2]:
                                for dr2 in range(-3, 4):
                                    for dc2 in range(-3, 4):
                                        s2 = set((r + dr2, c + dc2) for r, c in p2)
                                        if any(not (0 <= r < 4 and 0 <= c < 4) for r, c in s2):
                                            continue
                                        if not s0.isdisjoint(s2) and not s1.isdisjoint(s2):
                                            # Check full overlap
                                            combined = s0 | s1 | s2
                                            if len(combined) == 16:
                                                print("Yes")
                                                return
                                        # Re-check disjoint for all three
                                        if s0.isdisjoint(s2) and s1.isdisjoint(s2):
                                            if len(s0 | s1 | s2) == 16:
                                                print("Yes")
                                                return

    print("No")

if __name__ == "__main__":
    solve()
```

