                counts[char] = 0
                distinct_chars += 1
            counts[char] += 1

            # A string is balanced if:
            # total_length == distinct_chars * count_of_any_char
            # We can use the count of the first character encountered
            if (j - i) % distinct_chars == 0:
                target = (j - i) // distinct_chars
                # Verify all characters have this target count
                if all(c == target for c in counts.values()):
                    balanced[i][j] = True

    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n + 1):
            if balanced[i][j]:
                dp[i] = min(dp[i], 1 + dp[j])

    return dp[0]
