def maximumLength(s: str) -> int:
    n = len(s)
    # Dictionary to store the lengths of consecutive character blocks for each character
    # e.g., "aaabaa" -> {'a': [3, 2], 'b': [1]}
    counts = {}

    i = 0
    while i < n:
        char = s[i]
        length = 0
        while i < n and s[i] == char:
            length += 1
            i += 1

        if char not in counts:
            counts[char] = []
        counts[char].append(length)

    ans = -1

    for char in counts:
        lengths = sorted(counts[char], reverse=True)

        # We check three possibilities for the longest special substring occurring thrice:
        # 1. From the longest block of this character: length - 2
        if lengths[0] >= 3:
            ans = max(ans, lengths[0] - 2)

        # 2. Between the longest and second longest blocks:
        if len(lengths) >= 2:
            # If the longest is greater than the second, we can take min(L1-1, L2)
            # If L1 == L2, we can take L1-1
            if lengths[0] > lengths[1]:
                ans = max(ans, lengths[1])
            else:
                ans = max(ans, lengths[0] - 1)

        # 3. Between the three longest blocks:
        if len(lengths) >= 3:
            ans = max(ans, lengths[2])

    return ans if ans > 0 else -1
