import sys

def solve():
    # Read the 3x3 grid from stdin
    try:
        input_data = sys.stdin.read().split()
        if not input_data:
            return
        A = [int(x) for x in input_data]
    except EOFError:
        return

    # Winning lines in a 3x3 grid (indices 0-8)
    lines = [
        (0, 1, 2), (3, 4, 5), (6, 7, 8), # Rows
        (0, 3, 6), (1, 4, 7), (2, 5, 8), # Cols
        (0, 4, 8), (2, 4, 6)             # Diagonals
    ]

    memo = {}

    def get_winner(mask_t, mask_a, turn):
        """
        mask_t: bitmask of cells painted red (Takahashi)
        mask_a: bitmask of cells painted blue (Aoki)
        turn: 0 for Takahashi, 1 for Aoki
        Returns 1 if Takahashi wins, -1 if Aoki wins
        """
        state = (mask_t, mask_a, turn)
        if state in memo:
            return memo[state]

        # Check if the previous player won by completing a line
        # If it's Takahashi's turn, check if Aoki just completed a line
        if turn == 0: # Aoki just moved
            for r1, r2, r3 in lines:
                if (mask_a & (1 << r1)) and (mask_a & (1 << r2)) and (mask_a & (1 << r3)):
                    return -1
        else: # Takahashi just moved
            for r1, r2, r3 in lines:
                if (mask_t & (1 << r1)) and (mask_t & (1 << r2)) and (mask_t & (1 << r3)):
                    return 1

        # Check if board is full
        if (mask_t | mask_a) == 0b111111111:
            score_t = 0
            score_a = 0
            for i in range(9):
                if mask_t & (1 << i):
                    score_t += A[i]
                else:
                    score_a += A[i]
            return 1 if score_t > score_a else -1

        # Recursive step
        if turn == 0: # Takahashi's turn (Maximize)
            res = -1
            for i in range(9):
                if not ((mask_t | mask_a) & (1 << i)):
                    if get_winner(mask_t | (1 << i), mask_a, 1) == 1:
                        res = 1
                        break
            memo[state] = res
            return res
        else: # Aoki's turn (Minimize)
            res = 1
            for i in range(9):
                if not ((mask_t | mask_a) & (1 << i)):
                    if get_winner(mask_t, mask_a | (1 << i), 0) == -1:
                        res = -1
                        break
            memo[state] = res
            return res

    result = get_winner(0, 0, 0)
    if result == 1:
        print("Takahashi")
    else:
        print("Aoki")

if __name__ == "__main__":
