def stringIndices(wordsContainer, wordsQuery):
    # A Trie node will store the index of the "best" word found so far
    # passing through this node. "Best" is defined as:
    # 1. Shortest length
    # 2. Earliest index in wordsContainer
    class TrieNode:
        def __init__(self, best_idx):
            self.children = {}
            self.best_idx = best_idx

    # Helper to determine if index 'new_idx' is better than 'old_idx'
    def is_better(new_idx, old_idx):
        if old_idx == -1:
            return True
        len_new = len(wordsContainer[new_idx])
        len_old = len(wordsContainer[old_idx])
        if len_new < len_old:
            return True
        if len_new == len_old:
            return new_idx < old_idx
        return False

    # Find the global best index for the root (empty suffix)
    global_best_idx = 0
    for i in range(1, len(wordsContainer)):
        if is_better(i, global_best_idx):
            global_best_idx = i

    root = TrieNode(global_best_idx)

    # Build the Trie using reversed words for suffix matching
    for i, word in enumerate(wordsContainer):
        curr = root
        # Update root if this word is better than the current global best
        if is_better(i, root.best_idx):
            root.best_idx = i

        # Traverse backwards through the word
        for char in reversed(word):
            if char not in curr.children:
                curr.children[char] = TrieNode(i)
            else:
                if is_better(i, curr.children[char].best_idx):
                    curr.children[char].best_idx = i
            curr = curr.children[char]

    results = []
    # Query the Trie
    for query in wordsQuery:
        curr = root
        last_best = root.best_idx
        for char in reversed(query):
            if char in curr.children:
                curr = curr.children[char]
                last_best = curr.best_idx
            else:
                break
        results.append(last_best)

    return results
