def solve(a: str, b: str, c: str) -> str:
    import itertools

    def merge(s1, s2):
        # If s2 is already a substring of s1, return s1
        if s2 in s1:
            return s1
        # Find the maximum overlap where the suffix of s1 matches the prefix of s2
        for i in range(min(len(s1), len(s2)), 0, -1):
            if s1.endswith(s2[:i]):
                return s1 + s2[i:]
        return s1 + s2

    def get_shortest_superstring(s1, s2, s3):
        # Merge s1 and s2 first, then merge the result with s3
        res12 = merge(s1, s2)
        res123 = merge(res12, s3)

        # Also consider merging s2 and s3 first, then s1 with that result
        # because the merge function is not strictly associative for this problem
        res23 = merge(s2, s3)
        res231 = merge(res23, s1)

        # Return the better of the two paths for this specific permutation
        if len(res123) < len(res231):
            return res123
        elif len(res231) < len(res123):
            return res231
        else:
            return min(res123, res231)

    ans = None
    # Check all permutations of the three strings
    for p in itertools.permutations([a, b, c]):
        current = get_shortest_superstring(p[0], p[1], p[2])

        if ans is None:
            ans = current
        else:
            if len(current) < len(ans):
                ans = current
            elif len(current) == len(ans):
                if current < ans:
                    ans = current

    return ans
