import sys
from collections import deque

def solve():
    # Read H, W, T
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    H = int(input_data[0])
    W = int(input_data[1])
    T = int(input_data[2])
    grid = input_data[3:]

    start_pos = None
    goal_pos = None
    candies = []

    for r in range(H):
        for c in range(W):
            char = grid[r][c]
            if char == 'S':
                start_pos = (r, c)
            elif char == 'G':
                goal_pos = (r, c)
            elif char == 'o':
                candies.append((r, c))

    # Nodes: Start (0), Candies (1 to N), Goal (N+1)
    nodes = [start_pos] + candies + [goal_pos]
    num_nodes = len(nodes)
    num_candies = len(candies)

    # Precompute distances between all pairs of special nodes using BFS
    dist_matrix = [[float('inf')] * num_nodes for _ in range(num_nodes)]

    for i in range(num_nodes):
        sr, sc = nodes[i]
        dists = [[-1] * W for _ in range(H)]
        dists[sr][sc] = 0
        queue = deque([(sr, sc)])

        while queue:
            r, c = queue.popleft()
            d = dists[r][c]
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and dists[nr][nc] == -1:
                    dists[nr][nc] = d + 1
                    queue.append((nr, nc))

        for j in range(num_nodes):
            tr, tc = nodes[j]
            if dists[tr][tc] != -1:
                dist_matrix[i][j] = dists[tr][tc]

    # If goal is unreachable from start
    if dist_matrix[0][num_nodes - 1] > T:
        print("-1")
        return

    # DP for TSP-like problem: dp[mask][i] is min distance to visit candies in mask ending at candy i
    # mask is bitmask of candies (0 to num_candies-1)
    # i is index of candy (1 to num_candies)
    dp = [[float('inf')] * (num_candies + 1) for _ in range(1 << num_candies)]

    # Initial state: from start to each candy
    for i in range(num_candies):
        d = dist_matrix[0][i + 1]
        if d <= T:
            dp[1 << i][i + 1] = d

    # Fill DP
    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i + 1] == float('inf'):
                continue

            curr_dist = dp[mask][i + 1]
            # Try moving to another candy
            for next_candy in range(num_candies):
                if not (mask & (1 << next_candy)):
                    new_dist = curr_dist + dist_matrix[i + 1][next_candy + 1]
                    if new_dist <= T:
                        new_mask = mask | (1 << next_candy)
                        if new_dist < dp[new_mask][next_candy + 1]:
                            dp[new_mask][next_candy + 1] = new_dist

    # Check max candies such that dist(start -> candies) + dist(last candy -> goal) <= T
    max_candies = 0
    # Case 0: No candies visited
    if dist_matrix[0][num_nodes - 1] <= T:
        max_candies = 0

    for mask in range(1, 1 << num_candies):
        for i in range(num_candies):
            if dp[mask][i + 1] != float('inf'):
                if dp[mask][i + 1] + dist_matrix[i + 1][num_nodes - 1] <= T:
                    count = bin(mask).count('1')
                    if count > max_candies:
                        max_candies = count

    print(max_candies)

