def minimumCost(source: str, target: str, original: list[str], changed: list[str], cost: list[int]) -> int:
    # Initialize a 26x26 distance matrix with infinity
    # 26 represents the lowercase English letters 'a' through 'z'
    inf = float('inf')
    dist = [[inf] * 26 for _ in range(26)]

    # Distance from a character to itself is 0
    for i in range(26):
        dist[i][i] = 0

    # Fill the matrix with the given transformation costs
    for u, v, w in zip(original, changed, cost):
        u_idx = ord(u) - ord('a')
        v_idx = ord(v) - ord('a')
        # There might be multiple costs for the same transformation, keep the minimum
        if w < dist[u_idx][v_idx]:
            dist[u_idx][v_idx] = w

    # Floyd-Warshall algorithm to find the shortest path between all pairs of characters
    for k in range(26):
        for i in range(26):
            if dist[i][k] == inf:
                continue
            for j in range(26):
                if dist[k][j] < inf:
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    total_cost = 0
    for s_char, t_char in zip(source, target):
        if s_char == t_char:
            continue

        u_idx = ord(s_char) - ord('a')
        v_idx = ord(t_char) - ord('a')

        c = dist[u_idx][v_idx]
        if c == inf:
            return -1
        total_cost += c

    return total_cost
