            substring = s[i:j]
            # Check if the substring has exactly k ones
            if substring.count('1') == k:
                current_len = len(substring)

                # If we find a shorter beautiful substring, update shortest_len and res
                if current_len < shortest_len:
                    shortest_len = current_len
                    res = substring
                # If length is equal, pick the lexicographically smaller one
                elif current_len == shortest_len:
                    if substring < res:
