        return

    N = int(input_data[0])
    H = int(input_data[1])
    W = int(input_data[2])

    tiles = []
    idx = 3
    for _ in range(N):
        tiles.append((int(input_data[idx]), int(input_data[idx+1])))
        idx += 2

    # grid[r][c] is True if covered
    grid = [[False for _ in range(W)] for _ in range(H)]

    def find_empty():
        for r in range(H):
            for c in range(W):
                if not grid[r][c]:
                    return r, c
        return -1, -1

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(r, r + h):
            for j in range(c, c + w):
                if grid[i][j]:
                    return False
        return True

    def set_tile(r, c, h, w, val):
        for i in range(r, r + h):
            for j in range(c, c + w):
                grid[i][j] = val

    used = [False] * N

    def backtrack():
        r, c = find_empty()
        # If no empty cell is found, the grid is fully covered
        if r == -1:
            return True

        for i in range(N):
            if not used[i]:
                used[i] = True
                # Try original orientation and rotated orientation
                orientations = set([(tiles[i][0], tiles[i][1]), (tiles[i][1], tiles[i][0])])
                for h, w in orientations:
                    if can_place(r, c, h, w):
                        set_tile(r, c, h, w, True)
                        if backtrack():
                            return True
                        set_tile(r, c, h, w, False)
                used[i] = False
        return False

    if backtrack():
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
