def canTraverseAllPairs(nums: list[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    # If any number is 1 and there's more than one element, 
    # it can't be connected to anything.
    if 1 in nums:
        return False

    parent = list(range(n))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    # prime_to_index stores the first index encountered that is divisible by a prime
    prime_to_index = {}
    max_num = max(nums)

    # Sieve-like approach to find prime factors for each number
    # and union indices sharing the same prime factor
    for i, val in enumerate(nums):
        temp = val
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                if d in prime_to_index:
                    union(i, prime_to_index[d])
                else:
                    prime_to_index[d] = i
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            if temp in prime_to_index:
                union(i, prime_to_index[temp])
            else:
                prime_to_index[temp] = i

    # Check if all indices belong to the same component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True
