                        counts[char] += 1
                        if counts[char] > 1:
                            possible = False
                            break
                if not possible: break

            if possible:
                if backtrack(row_idx + 1):
                    return True
        return False

    if backtrack(0):
        print("Yes")
        for row in grid:
            print("".join(row))
